function calculateTotal(items: {price:number, qty:number}[], taxRate: number) {
  let subtotal = 0;
  for (const i of items) {
    subtotal += i.price * i.qty;
  }
  return Math.round((subtotal * (1 + taxRate)) * 100) / 100;
}

function finalizeOrder(order: any) {
  if (!order) throw new Error("no order");
  if (!order.items || order.items.length === 0) return null;
  let total = 0;
  for (const it of order.items) {
    if (it.price === undefined) it.price = 0;
    total += it.price * (it.quantity || 1);
  }
  if (order.coupon) total *= 0.9;
  return { total, processedAt: new Date().toISOString() };
}

// Version A: compose small functions
function buildReport(data: any) {
  const filtered = filterBadRows(data);
  const transformed = transformRows(filtered);
  return formatReport(transformed);
}

// Version B: single function doing everything inline
function buildReportV2(data: any) {
  const result: any[] = [];
  for (const r of data) {
    if (!r.active) continue;
    const t = { id: r.id, value: r.value * 1.2 };
    result.push(t);
  }
  return JSON.stringify(result);
}
